57	/// The internal representation of a subgraph schema, i.e., the
58	/// `schema.graphql` file that is part of a subgraph. Any code that deals
59	/// with writing a subgraph should use this struct. Code that deals with
60	/// querying subgraphs will instead want to use an `ApiSchema` which can be
61	/// generated with the `api_schema` method on `InputSchema`
62	///
63	/// There's no need to put this into an `Arc`, since `InputSchema` already
64	/// does that internally and is `CheapClone`
65	#[derive(Clone, CheapClone, Debug, PartialEq)]
66	pub struct InputSchema {
67	    inner: Arc<Inner>,
68	}
